Recursive‑descent parser over `fractions.Fraction`:

```python
import re
from fractions import Fraction

_TOKEN_RE = re.compile(r'\s*(\d+\s*/\s*\d+|\d+|[+\-*()])')


def fraction_expr(s: str) -> str:
    if not isinstance(s, str):
        raise ValueError("input must be a string")

    # --- tokenize -------------------------------------------------------
    tokens = []
    pos = 0
    n = len(s)
    while pos < n:
        if s[pos].isspace():
            pos += 1
            continue
        m = _TOKEN_RE.match(s, pos)
        if not m or m.start(1) != pos:
            # allow the regex to have skipped whitespace only
            if not m:
                raise ValueError("invalid character at position %d" % pos)
        tok = m.group(1)
        if '/' in tok:
            tok = re.sub(r'\s+', '', tok)
        tokens.append(tok)
        pos = m.end(1)

    if not tokens:
        raise ValueError("empty expression")

    idx = 0

    def peek():
        return tokens[idx] if idx < len(tokens) else None

    def advance():
        nonlocal idx
        t = tokens[idx]
        idx += 1
        return t

    def parse_expr():
        value = parse_term()
        while peek() in ('+', '-'):
            op = advance()
            rhs = parse_term()
            value = value + rhs if op == '+' else value - rhs
        return value

    def parse_term():
        value = parse_factor()
        while peek() == '*':
            advance()
            value = value * parse_factor()
        return value

    def parse_factor():
        t = peek()
        if t == '-':
            advance()
            return -parse_factor()
        if t == '+':
            advance()
            return parse_factor()
        return parse_atom()

    def parse_atom():
        t = peek()
        if t is None:
            raise ValueError("unexpected end of expression")
        if t == '(':
            advance()
            value = parse_expr()
            if peek() != ')':
                raise ValueError("missing closing parenthesis")
            advance()
            return value
        if t[0].isdigit():
            advance()
            if '/' in t:
                num, den = t.split('/')
                if int(den) == 0:
                    raise ValueError("zero denominator")
                return Fraction(int(num), int(den))
            return Fraction(int(t))
        raise ValueError("unexpected token %r" % t)

    result = parse_expr()
    if idx != len(tokens):
        raise ValueError("unexpected token %r" % tokens[idx])

    if result.denominator == 1:
        return str(result.numerator)
    return "%d/%d" % (result.numerator, result.denominator)
```

The tokenizer rejects stray characters (so things like `3/4/5` or `1 / 2` used as division fail), the parser rejects unbalanced parentheses and dangling operators, and zero denominators raise `ValueError`.
